import { chromium, type Browser } from 'playwright-core';
import { errorMessage } from '../utils/errorMessage';

const BROWSER_CHANNELS = [undefined, 'chrome', 'msedge'];
const VIEWPORT = { width: 1280, height: 800 };
const CAPTURE_TIMEOUT_MS = 15_000;
const SETTLE_MS = 500;
const JPEG_QUALITY = 70;

export class ProjectScreenshotService {
  private pending: Promise<unknown> = Promise.resolve();
  private browser: Browser | null = null;
  private isClosed = false;

  capture(url: string): Promise<string> {
    const pending = this.pending.then(() => this.render(url));
    this.pending = pending.catch(() => undefined);
    return pending;
  }

  async close(): Promise<void> {
    this.isClosed = true;
    await this.browser?.close();
    await this.pending;
  }

  private async launch(): Promise<Browser> {
    const failures: string[] = [];
    for (const channel of BROWSER_CHANNELS) {
      try {
        return await chromium.launch({
          channel,
          headless: true,
          timeout: CAPTURE_TIMEOUT_MS,
        });
      } catch (error) {
        failures.push(`${channel ?? 'bundled'}: ${errorMessage(error)}`);
      }
    }
    throw new Error(
      `No installed browser is available for project previews (${failures.join('; ')})`,
    );
  }

  private async render(url: string): Promise<string> {
    if (this.isClosed) throw new Error('Project screenshot service is closed');
    this.browser = await this.launch();
    const browser = this.browser;
    let timeout: ReturnType<typeof setTimeout> | undefined;
    try {
      if (this.isClosed)
        throw new Error('Project screenshot service is closed');
      const page = await browser.newPage({
        viewport: VIEWPORT,
        deviceScaleFactor: 1,
        reducedMotion: 'reduce',
        serviceWorkers: 'block',
      });
      page.setDefaultTimeout(CAPTURE_TIMEOUT_MS);
      timeout = setTimeout(() => {
        void browser.close();
      }, CAPTURE_TIMEOUT_MS);
      const response = await page.goto(url, { waitUntil: 'load' });
      if (!response?.ok())
        throw new Error('The project preview could not load');
      await page.evaluate(async () => {
        await document.fonts.ready;
      });
      await page.waitForTimeout(SETTLE_MS);
      const bytes = await page.screenshot({
        type: 'jpeg',
        quality: JPEG_QUALITY,
        animations: 'disabled',
      });
      return `data:image/jpeg;base64,${bytes.toString('base64')}`;
    } finally {
      clearTimeout(timeout);
      await browser.close();
      this.browser = null;
    }
  }
}
